package com.salespunch360.mobile.ui.account.accounting
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun AssetScreen(padding:PaddingValues,vm:AccountAssetViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search assets")},modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton(vm::create){Icon(Icons.Default.Add,"New asset")}};LazyRow{items(listOf<String?>(null,"ACTIVE","ASSIGNED","UNDER_MAINTENANCE","DISPOSED","RETIRED")){v->FilterChip(s.status==v,{vm.filter(v)},{Text(v?.replace('_',' ')?:"All")})}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(s.rows,key={it.str("id")}){x->ListItem(headlineContent={Text("${x.str("assetNumber")} · ${x.str("name")}",fontWeight=FontWeight.Bold)},supportingContent={Text("${x.str("assetType")} · ${x.str("depreciationMethod")}")},trailingContent={Text(x.str("status"))},modifier=Modifier.clickable{vm.open(x.str("id"))})}}};s.editing?.let{AssetEditor(it,s.options,vm::close,vm::save)};s.detail?.let{AssetDetail(it,s.options,vm::close,vm::edit,vm::action)}}
@Composable private fun AssetEditor(x:JsonObject,o:JsonObject,close:()->Unit,save:(JsonObject)->Unit){val edit=x.containsKey("id");var name by remember{mutableStateOf(x.str("name"))};var type by remember{mutableStateOf(x.str("assetType").ifBlank{"OTHER"})};var category by remember{mutableStateOf(x.str("category"))};var branch by remember{mutableStateOf(x.str("branchId"))};var date by remember{mutableStateOf(x.str("purchaseDate").take(10).ifBlank{java.time.LocalDate.now().toString()})};var value by remember{mutableStateOf(x.str("purchaseValue"))};var salvage by remember{mutableStateOf(x.str("salvageValue").ifBlank{"0"})};var method by remember{mutableStateOf(x.str("depreciationMethod").ifBlank{"NONE"})};var life by remember{mutableStateOf(x.str("usefulLifeMonths"))};AlertDialog(onDismissRequest=close,title={Text(if(edit)"Edit asset" else "New asset")},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{OutlinedTextField(name,{name=it},label={Text("Asset name")})};item{TextOption("Asset type",type,listOf("LAND","BUILDING","VEHICLE","MACHINERY","EQUIPMENT","FURNITURE","COMPUTER","OTHER")){type=it}};item{OutlinedTextField(category,{category=it},label={Text("Category")})};if(!edit)item{Option("Branch",branch,o.array("branches")){branch=it}};item{OutlinedTextField(date,{date=it},label={Text("Acquisition date")})};item{OutlinedTextField(value,{value=it},label={Text("Acquisition value")})};item{TextOption("Depreciation",method,listOf("NONE","STRAIGHT_LINE","WRITTEN_DOWN_VALUE")){method=it}};if(method!="NONE")item{OutlinedTextField(life,{life=it},label={Text("Useful life in months")})};item{OutlinedTextField(salvage,{salvage=it},label={Text("Salvage value")})}}},confirmButton={Button(enabled=name.isNotBlank()&&value.isNotBlank()&&(edit||branch.isNotBlank()),onClick={save(buildJsonObject{if(!edit)put("branchId",branch);put("name",name);put("assetType",type);category.takeIf{it.isNotBlank()}?.let{put("category",it)};put("purchaseDate",date);put("purchaseValue",value);put("depreciationMethod",method);if(method!="NONE"){put("usefulLifeMonths",life);put("depreciationStartDate",date)};put("salvageValue",salvage)})}){Text("Save")}},dismissButton={TextButton(close){Text("Cancel")}})}
@Composable private fun AssetDetail(d:JsonObject,o:JsonObject,close:()->Unit,edit:()->Unit,action:(String,JsonObject)->Unit){val x=d["asset"]!!.jsonObject;var user by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text(x.str("assetNumber"))},text={LazyColumn{item{Text(x.str("name"),style=MaterialTheme.typography.titleLarge)};item{Text("${x.str("assetType")} · ${x.str("status")}")};item{Text("Acquired ${x.str("purchaseDate").take(10)} · ₹${x.str("purchaseValue")}")};item{Text("Depreciation ${x.str("depreciationMethod")} · life ${x.str("usefulLifeMonths")} months")};items(d.array("history")){h->Text("Assignment ${h.jsonObject.str("assignedAt").take(10)}")};if(x.str("status")=="ACTIVE")item{Option("Assign to user",user,o.array("users")){user=it}}}},confirmButton={Row{Button(edit){Text("Edit")};if(x.str("status")=="ACTIVE"&&user.isNotBlank())OutlinedButton({action(x.str("id"),buildJsonObject{put("action","ASSIGN");put("userId",user)})}){Text("Assign")};if(x.str("status")=="ASSIGNED")OutlinedButton({action(x.str("id"),buildJsonObject{put("action","RETURN")})}){Text("Return")};if(x.str("status") in listOf("ACTIVE","UNDER_MAINTENANCE"))OutlinedButton({action(x.str("id"),buildJsonObject{put("action","STATUS");put("status","DISPOSED")})}){Text("Dispose")}}},dismissButton={TextButton(close){Text("Close")}})}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun TextOption(label:String,value:String,values:List<String>,set:(String)->Unit){var open by remember{mutableStateOf(false)};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(value,{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{v->DropdownMenuItem({Text(v.replace('_',' '))},{set(v);open=false})}}}}
